function notify(text,now){
if(demo||!state.configured||document.hidden||!$('overlay').hidden||state.reminderMode==='off')return false;
var day=C.key(now),time=now.getTime(),r=state.reminders;
if(!r||r.day!==day)r={day:day,highest:0,lastAt:r&&r.lastAt||0,count:0};
if(r.count>=3||time-r.lastAt<3600000)return false;
r.lastAt=time;r.count++;state.reminders=r;toast(state.displayMode==='private'?(text.indexOf('攒够')>=0?'✦ 有一个小目标点亮了。':'☕ 又攒下一点喜欢，继续加油。'):text);
if(state.reminderMode!=='text'&&api&&typeof api.vibrateShort==='function')api.vibrateShort({type:'light'}).catch(function(){});
return true;
}
function checkMilestones(v,now){
if(demo||!state.configured||document.hidden||!$('overlay').hidden)return;
var day=C.key(now),time=now.getTime(),r=state.reminders;
if(!r||r.day!==day)r={day:day,highest:0,lastAt:r&&r.lastAt||0,count:0};
var levels=[{amount:20,text:'☕ 你已经赚到一杯咖啡了。'},{amount:50,text:'🍜 今天的饭钱，赚到啦。'},{amount:100,text:'✨ 今天已经赚到 100 元，辛苦有回声。'},{amount:200,text:'🌿 今日进账 200 元，离小目标又近一步。'}];
var hit=null;levels.forEach(function(item){if(v.today>=item.amount&&item.amount>r.highest)hit=item;});
if(!hit)return;
if(notify(hit.text,now)){state.reminders.highest=hit.amount;save();}
}
